        }

        .status-info h3 {
            color: #856404;
            margin-bottom: 10px;
        }

        .status-info p {
            color: #856404;
            line-height: 1.6;
        }

        .retry-section {
            margin: 30px 0;
        }

        .countdown {
            font-size: 48px;
            font-weight: bold;
            color: #f39c12;
            margin: 20px 0;
        }

        .actions {
            display: flex;
            gap: 15px;
            justify-content: center;
            flex-wrap: wrap;
        }

        .btn {
            display: inline-block;
            padding: 14px 28px;
            border-radius: 8px;
            text-decoration: none;
            font-weight: 500;
            transition: all 0.3s;
            border: none;
            cursor: pointer;
            font-size: 16px;
        }

        .btn-primary {
            background: #27ae60;
            color: white;
        }

        .btn-primary:hover {
            background: #229954;
        }

        .btn-secondary {
            background: #ecf0f1;
            color: #2c3e50;
        }

        @media (max-width: 768px) {
            .error-container {
                padding: 40px 20px;
            }

            .error-code {
                font-size: 80px;
            }

            .actions {
                flex-direction: column;
            }

            .btn {
                width: 100%;
            }
        }
    </style>
</head>
<body>
    <div class="error-container">
        <div class="error-icon">🌐</div>
        <div class="error-code">503</div>
        <h1 class="error-title">天気情報を取得できません</h1>
        <p class="error-message" th:text="${errorMessage} ?: '外部APIに接続できませんでした'">
            外部APIに接続できませんでした
        </p>

        <div class="status-info">
            <h3>💡 考えられる原因</h3>
            <p>
                • 天気情報提供サービスが一時的に利用できない<br>
                • ネットワーク接続に問題がある<br>
                • サーバーのメンテナンス中
            </p>
        </div>

        <div class="retry-section" th:if="${retryUrl}">
            <p>自動的に再試行します...</p>
            <div class="countdown" id="countdown">10</div>
        </div>

        <div class="actions">
            <a th:href="${retryUrl}" th:if="${retryUrl}" class="btn btn-primary">今すぐ再試行</a>
            <a href="/" class="btn btn-secondary">トップページに戻る</a>
        </div>
    </div>

    <script th:if="${retryUrl}">
        let countdown = 10;
        const countdownEl = document.getElementById('countdown');
        const retryUrl = /*[[${retryUrl}]]*/ '/';

        const timer = setInterval(() => {
            countdown--;
            if (countdownEl) {
                countdownEl.textContent = countdown;
            }

            if (countdown <= 0) {
                clearInterval(timer);
                window.location.href = retryUrl;
            }
        }, 1000);
    </script>
</body>
</html>
```

